/* Fade and rise over the first 320px of scroll after the element's top enters the window (a
   fixed distance, so things already in the first screen are in place at load). Each step
   shifts the range by 80px, so a row arrives one after another. Only where view timelines are
   supported and motion is allowed; otherwise everything is simply there. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .structureengineering-reveal {
      animation: structureengineering-reveal-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--se-reveal-step, 0) * 80px) entry calc(320px + var(--se-reveal-step, 0) * 80px);
    }
  }
}

@keyframes structureengineering-reveal-in {
  from {
    opacity: 0;
    transform: translateY(var(--se-reveal-rise, 48px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./structureengineering-reveal.css";

export interface StructureengineeringRevealProps {
  children?: ReactNode;
  /** the element to render (div by default; li inside lists, span inside headings) */
  as?: ElementType;
  /** position in a staggered group: 0, 1, 2… each arrives a little later */
  step?: number;
  /** how far it rises, in px (the original uses 48) */
  rise?: number;
  className?: string;
}

// Fades in and rises as it enters the window, driven by the scroll (CSS only).
export function StructureengineeringReveal({ children, as: Tag = "div", step = 0, rise = 48, className }: StructureengineeringRevealProps) {
  return (
    <Tag
      className={cn("structureengineering-reveal", className)}
      style={{ "--se-reveal-step": step, "--se-reveal-rise": `${rise}px` } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
